AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(
    const ScoredHistoryMatch* history_match,
    int score) {
  AutocompleteMatch match;
  match.score = score;
  match.fill_into_match(history_match->url, history_match->title);
  match.contents = history_match->url;
  match.description = history_match->title;
  match.is_history_match = true;

  if (history_match->is_inline_autocomplete) {
    match.destination_url = history_match->inline_autocomplete_url;
  } else {
    match.destination_url = history_match->url;
  }

  match.type = AutocompleteMatchType::HISTORY_TITLE;
  match.relevance = history_match->relevance;

  // Format term matches for URL and title
  FormatTermMatches(history_match->url, history_match->title, &match);

  return match;
}

