    match.url = history_match->url;
    match.description = FormatDescriptionForDisplay(history_match->description);
    match.inline_autocomplete_offset = GetInlineAutocompleteOffset(history_match->url);
    FormatTermMatches(&(match.url), history_match->url, history_match->term);
    FormatTermMatches(&(match.description), history_match->title, history_match->term);
    return match;
}

AutocompleteMatch ConvertScoredHistoryMatchToAutocompleteMatch(const ScoredHistoryMatch* history_match, int score) {
    AutocompleteMatch match;
    match.url = history_match->url;
    match.description = FormatDescription(history_match->title, history_match->url);
    match.score = score;
    match.inline_autocomplete_offset = -1;

    if (history_match->match_type & MATCH_TYPE_INLINE_AUTOCOMPLETE) {
        match.inline_autocomplete_offset = FindInlineOffset(history_match->title, history_match->url);
    }

    FormatTermMatches(&match, history_match->title, history_match->url);
    return match;
}
